WITH exploded AS (SELECT id, service, log_ts, level, latency_ms, key, value FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, value), cleaned AS (SELECT id, service, level, latency_ms, key, value, INITCAP(TRIM(service)) AS service_title, COALESCE(key, 'NONE') AS resolved_key FROM exploded WHERE key IS NOT NULL AND key IS DISTINCT FROM 'version'), filtered AS (SELECT id, service, level, latency_ms, key, value, service_title, resolved_key, CASE WHEN latency_ms >= 2035 THEN 'High' WHEN latency_ms >= 1125 THEN 'Medium' ELSE 'Low' END AS latency_ms_tier FROM cleaned WHERE key IS NOT NULL AND key IS DISTINCT FROM 'region'), filtered_app_logs AS (SELECT *, LENGTH(level) AS level_length, INITCAP(TRIM(service)) AS service_title_2 FROM filtered WHERE key IS DISTINCT FROM 'trace' AND level = 'ERROR') SELECT key, service, COUNT(CASE WHEN service = 'checkout' THEN 1 END) AS checkout_count, COUNT(*) FILTER (WHERE level = 'DEBUG') AS debug_rows, MAX(level_length) AS max_level_length, MAX(latency_ms) AS max_latency_ms, ROUND(SUM(level_length) / NULLIF(COUNT(CASE WHEN service = 'search' THEN 1 END), 0), 2) AS level_length_per_search FROM filtered_app_logs GROUP BY GROUPING SETS ((key, service), (key))
